import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sigmoid_kernel_fused(const float4* __restrict__ input4,
                                     float4* __restrict__ output4,
                                     int64_t n_vec4,
                                     const float* __restrict__ input,
                                     float* __restrict__ output,
                                     int64_t n,
                                     int64_t offset) {
    const int64_t tid = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    const int64_t stride = gridDim.x * (int64_t)blockDim.x;
    // Grid-stride loop over float4 elements with manual unrolling (process 4 vectors per iteration)
    // to increase instruction-level parallelism and use read-only cache (__ldg) for input loads.
    #pragma unroll 8
    for (int64_t i = tid; i < n_vec4; i += stride) {
        float4 in = __ldg(&input4[i]);
        float4 out;
        out.x = __fdividef(1.0f, 1.0f + __expf(-in.x));
        out.y = __fdividef(1.0f, 1.0f + __expf(-in.y));
        out.z = __fdividef(1.0f, 1.0f + __expf(-in.z));
        out.w = __fdividef(1.0f, 1.0f + __expf(-in.w));
        // Streaming store: output is write-once and not reused soon,
        // so bypass polluting the cache hierarchy with it.
        __stcs(&output4[i], out);
    }
    // Parallel tail handling: distribute the remainder elements across
    // all threads instead of serializing them on a single thread.
    #pragma unroll 4
    for (int64_t j = offset + tid; j < n; j += stride) {
        __stcs(&output[j], __fdividef(1.0f, 1.0f + __expf(-__ldg(&input[j]))));
    }
}
torch::Tensor sigmoid_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    auto x_contig = x.contiguous();
    auto output = torch::empty_like(x_contig);
    const int64_t n = x_contig.numel();
    const int64_t n_vec4 = n / 4;
    const int64_t offset = n_vec4 * 4;
    const float* input_ptr = x_contig.data_ptr<float>();
    float* output_ptr = output.data_ptr<float>();
    const int threads = 128;
    int64_t blocks = (n_vec4 + (int64_t)threads * 8 - 1) / ((int64_t)threads * 8);
    if (blocks < 1) blocks = 1;
    if (blocks > 1048576) blocks = 1048576;
    sigmoid_kernel_fused<<<blocks, threads>>>(
        reinterpret_cast<const float4*>(input_ptr),
        reinterpret_cast<float4*>(output_ptr),
        n_vec4,
        input_ptr,
        output_ptr,
        n,
        offset
    );
    return output;
}
"""

sigmoid_cpp_source = "torch::Tensor sigmoid_cuda(torch::Tensor x);"

sigmoid_module = load_inline(
    name="sigmoid_module",
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_source,
    functions=["sigmoid_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sigmoid_op = sigmoid_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sigmoid_op.sigmoid_cuda(x)


